/*==============================================================*/
/* Sincronizacao de equipamento                                 */
/* Mesma regra da trigger tg_manutencao_atualiza_equipamento.   */
/* Garante dados consistentes mesmo se o DML rodar antes da     */
/* criacao da trigger.                                          */
/*==============================================================*/
UPDATE e
   SET e.dt_ultima_manutencao = (SELECT MAX(m.dt_manutencao)
                                   FROM manutencao_equipamento m
                                  WHERE m.cd_equipamento = e.cd_equipamento
                                    AND m.st_manutencao = 'C'),
       e.st_equipamento = CASE
           WHEN e.st_equipamento = 'X' THEN 'X'
           WHEN EXISTS (SELECT 1 FROM manutencao_equipamento m
                         WHERE m.cd_equipamento = e.cd_equipamento
                           AND m.st_manutencao = 'A') THEN 'M'
           ELSE 'D' END
  FROM equipamento e;
GO

